/* The painting this site sits on, the way Monet Shot frames a take.
   The page becomes a sheet with rounded corners, the painting fills the margin around it.
   Off with ?record (Monet Shot adds its own painting when you record), with ?bare, and when the
   page is shown inside a frame. Swap painting.webp for another to change it; delete the
   <script src="./backdrop/backdrop.js"> line in index.html to drop it. */
(function () {
  var q = new URLSearchParams(location.search), d = document.documentElement;
  if (q.has('record') || q.has('bare')) return;
  try { if (window.top !== window.self && !q.has('backdrop')) return; } catch (e) { return; }
  var me = document.currentScript, src = (me && me.src || '').replace(/[^/]*$/, '') + 'painting.webp';
  d.classList.add('sf-backdrop');
  var s = document.createElement('style');
  s.textContent =
    'html.sf-backdrop{--bd-m:clamp(10px,3.4vw,48px);background:#2a251f url("' + src + '") center/cover fixed!important;min-height:100%}' +
    'html.sf-backdrop>body{box-sizing:border-box;margin:var(--bd-m) auto!important;width:calc(100% - 2 * var(--bd-m));' +
    'min-height:calc(100vh - 2 * var(--bd-m));border-radius:clamp(10px,1.2vw,16px);overflow:clip;' +
    'box-shadow:0 34px 80px -28px rgba(12,10,7,.7),0 0 0 1px rgba(0,0,0,.1)}';
  (document.head || d).appendChild(s);
  // A page that painted its colour on <html> and left <body> clear keeps that colour on the sheet.
  function sheet() {
    var b = document.body; if (!b) return;
    if (getComputedStyle(b).backgroundColor.replace(/\s/g, '') !== 'rgba(0,0,0,0)') return;
    d.classList.remove('sf-backdrop');
    var c = getComputedStyle(d).backgroundColor;
    d.classList.add('sf-backdrop');
    b.style.backgroundColor = c.replace(/\s/g, '') === 'rgba(0,0,0,0)' ? '#fff' : c;
  }
  // A fixed bar across the top (or bottom) of the page stays on the sheet, not over the painting.
  var bars = [];
  function findBars() {
    var b = document.body; if (!b) return;
    bars = [];
    b.querySelectorAll('*').forEach(function (el) {
      var cs = getComputedStyle(el); if (cs.position !== 'fixed') return;
      var r = el.getBoundingClientRect();
      if (r.width >= innerWidth * 0.9 && r.height < innerHeight * 0.4) bars.push({el: el, top: r.top < innerHeight / 2});
    });
    place();
  }
  function place() {
    if (!bars.length) return;
    var m = parseFloat(getComputedStyle(document.body).marginLeft) || 0;
    var below = d.scrollHeight - scrollY - innerHeight;
    bars.forEach(function (x) {
      var s = x.el.style; s.left = m + 'px'; s.right = m + 'px'; s.width = 'auto';
      if (x.top) s.top = Math.max(0, m - scrollY) + 'px'; else s.bottom = Math.max(0, m - below) + 'px';
    });
  }
  function ready() { sheet(); findBars(); }
  document.addEventListener('DOMContentLoaded', ready);
  addEventListener('load', ready);
  addEventListener('scroll', place, {passive: true});
  addEventListener('resize', findBars);
})();

/* StyleFeatures scaffolds: shared runtime. Safe to load twice.
   - [data-reveal] fades in on scroll
   - .ph-video gets a play/pause button, a running timeline and a timecode, so a video slot behaves like one
     (data-dur="12" seconds, data-autoplay for background loops)
   - press N (or ?clean in the URL) to hide the notes */
if (!window.__sfScaffold) {
  window.__sfScaffold = true;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }),
    { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
  const PLAY = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.8v12.4L16 10z" fill="currentColor"/></svg>';
  const PAUSE = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z" fill="currentColor"/></svg>';
  const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

  function video(el) {
    if (el.__sf) return; el.__sf = true;
    const dur = +el.dataset.dur || 12, loop = el.hasAttribute('data-autoplay') || el.hasAttribute('data-loop');
    const btn = document.createElement('button');
    btn.className = 'ph-play'; btn.type = 'button'; btn.setAttribute('aria-label', 'Play video'); btn.innerHTML = PLAY;
    const bar = document.createElement('div'); bar.className = 'ph-bar'; bar.setAttribute('aria-hidden', 'true');
    bar.innerHTML = `<span class="t">0:00</span><span class="ph-track"><i></i></span><span>${fmt(dur)}</span>`;
    if (el.hasAttribute('data-nobar')) bar.hidden = true;
    if (el.hasAttribute('data-nobutton')) btn.hidden = true;
    el.append(btn, bar);
    const t = bar.querySelector('.t');
    let pos = 0, playing = false, last = 0, raf = 0, visible = true;
    const draw = () => { el.style.setProperty('--p', pos / dur); t.textContent = fmt(pos); el.style.setProperty('--sf-t', pos); };
    const tick = (now) => {
      if (!playing) return;
      pos += Math.min(.1, (now - last) / 1000); last = now;
      if (pos >= dur) { if (loop) pos = 0; else { pos = dur; set(false); } }
      draw(); el.dispatchEvent(new CustomEvent('sf:time', { detail: { t: pos, dur } }));
      if (visible) raf = requestAnimationFrame(tick);
    };
    function set(on) {
      playing = on; el.classList.toggle('is-playing', on);
      btn.innerHTML = on ? PAUSE : PLAY; btn.setAttribute('aria-label', on ? 'Pause video' : 'Play video');
      cancelAnimationFrame(raf);
      if (on) { if (pos >= dur) pos = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    }
    btn.addEventListener('click', (e) => { e.stopPropagation(); set(!playing); });
    el.sfVideo = { play: () => set(true), pause: () => set(false), seek: (s) => { pos = Math.max(0, Math.min(dur, s)); draw(); }, get t() { return pos; }, dur };
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && playing) { last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(tick); } }).observe(el);
    if (el.hasAttribute('data-autoplay') && !reduce) set(true);
    draw();
  }

  const scan = (root = document) => {
    root.querySelectorAll('[data-reveal]:not(.is-in)').forEach((el) => (reduce ? el.classList.add('is-in') : io.observe(el)));
    root.querySelectorAll('.ph-video').forEach(video);
  };
  window.sfScan = scan;
  window.sfVideo = video;
  const boot = () => scan();
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', boot); else boot();
  if (location.search.includes('clean')) document.documentElement.classList.add('sf-clean');
  if (location.search.includes('thumb')) document.documentElement.classList.add('sf-thumb');
  if (innerWidth < 700) addEventListener('DOMContentLoaded', () => document.querySelector('.sf-spec')?.classList.add('is-min'));
  addEventListener('keydown', (e) => { if (e.key === 'n' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) document.documentElement.classList.toggle('sf-clean'); });
  const down = () => document.documentElement.classList.toggle('is-down', scrollY > 24);
  addEventListener('scroll', down, { passive: true }); down();
}

// demo/scholar: the paper. Picks the layout for the stage (the title page wide, square or tall; on a phone the title page
// alone in one narrow column), hands that layout's script to the engine, reads the title page once when it is on screen,
// then gives every reference on it to the visitor: Fig. 1 enlarges, [1] lights its paper, Cite opens the BibTeX and Copy
// copies it, PDF opens the preview at its highlighted sentence, the asterisk goes to the final footnote. Below, the paper
// goes on: sidenotes light (or open, on narrow screens) from their marks, and a running head follows the reader.
// ?t=12.5 freezes a moment; ?record&ratio=16:9|1:1|9:16 is a clean stage for screen recording (../tour/README.md).
import { Tour } from '../tour/tour.js';
import { film } from './script.js';

const q = new URLSearchParams(location.search);
const shape = (r) => (r < .8 ? 'tall' : r < 1.15 ? 'square' : 'wide');     // the engine's own thresholds
const PHONE = 700;                                                          // narrower than this: the title page alone

export default function init(root) {
  const stage = root.querySelector('[data-tour-stage]');
  const win = root.querySelector('[data-tour-window]');
  const page = win.querySelector('.sc-page');
  const rec = q.has('record'), fixed = q.has('t'), thumb = q.has('thumb');
  const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const off = [];

  const ratio = () => {
    if (rec) { const [a, b] = (q.get('ratio') || '16:9').split(':').map(Number); return a > 0 && b > 0 ? a / b : 16 / 9; }
    return innerWidth / Math.max(520, innerHeight);
  };
  const kindNow = () => (!rec && innerWidth < PHONE ? 'narrow' : shape(ratio()));

  // a phone: the window is the title page alone, 400 design px wide and as tall as it is (everything closed)
  function measureNarrow() {
    root.classList.add('is-narrow', 'is-measuring');
    const w = win.style.width; win.style.width = '400px';
    root.style.setProperty('--nh', Math.ceil(page.offsetHeight));
    win.style.width = w; root.classList.remove('is-measuring');
  }

  let kind = kindNow();
  root.classList.toggle('is-narrow', kind === 'narrow');
  if (kind === 'narrow') measureNarrow();
  const tour = new Tour(root, film(kind), { camera: kind === 'narrow' ? 'off' : undefined });
  root.tour = tour;
  off.push(() => tour.destroy());
  if (rec) return () => off.forEach((f) => f());
  win.removeAttribute('aria-hidden');       // on the page the title page is the real thing, not a picture of it

  const on = (el, ev, fn, o) => { el?.addEventListener(ev, fn, o); off.push(() => el?.removeEventListener(ev, fn, o)); };
  const isYours = () => root.classList.contains('is-yours');
  const fig = win.querySelector('.sc-fig'), veil = win.querySelector('.sc-veil'), pdf = win.querySelector('.sc-pdf');

  // ── after the film: the title page is the visitor's ──
  function yours(v) {
    root.classList.toggle('is-yours', v); page.scrollTop = 0;
    if (v) win.querySelectorAll('.is-hover, .is-press').forEach((e) => e.classList.remove('is-hover', 'is-press'));   // the film's cursor has left
    grow(); label();
  }
  function finish() { tour.pause(); tour.render(tour.duration, true); yours(true); }
  function closeAll() {
    setFig(false); setPdf(false);
    win.querySelectorAll('.sc-pub[data-open]').forEach((p) => cite(p, false));
  }
  function again() { closeAll(); yours(false); tour.render(0, true); tour.play(); label(); }

  function setFig(v) {
    fig?.classList.toggle('is-big', v); root.classList.toggle('is-fig-big', v); veil?.classList.toggle('is-on', v);
    if (v) setPdf(false);
    setTimeout(grow, 720);
  }
  function setPdf(v) {
    root.classList.toggle('is-pdf-open', v); pdf?.setAttribute('aria-hidden', String(!v)); veil?.classList.toggle('is-on', v || root.classList.contains('is-fig-big'));
    if (v) { root.classList.remove('is-fig-big'); fig?.classList.remove('is-big'); pdf?.querySelector('.sc-pdf-x')?.focus({ preventScroll: true }); }
  }
  // Cite: open the entry's BibTeX (one at a time on the title page); keep it in view inside the page
  function cite(pub, v = !pub.hasAttribute('data-open')) {
    pub.toggleAttribute('data-open', v);
    pub.querySelector('[data-cite]')?.setAttribute('aria-expanded', String(v));
    if (!v) pub.querySelector('.sc-bib-in')?.classList.remove('is-copied');
    if (page.contains(pub)) {
      if (v) win.querySelectorAll('.sc-pub[data-open]').forEach((p) => p !== pub && cite(p, false));
      setTimeout(() => {
        if (kind === 'narrow') { grow(); return; }
        const k = win.getBoundingClientRect().width / win.offsetWidth || 1;
        const pr = page.getBoundingClientRect(), br = pub.getBoundingClientRect();
        const over = (br.bottom - pr.bottom) / k + 24;
        page.scrollTo({ top: v && over > 0 ? page.scrollTop + over : 0, behavior: reduced ? 'auto' : 'smooth' });
      }, v ? 380 : 0);
    }
  }
  async function copy(btn) {
    const box = btn.closest('.sc-bib-in'), tex = box?.querySelector('.sc-tex');
    if (!tex) return;
    try { await navigator.clipboard.writeText(tex.textContent.trim()); } catch {
      const r = document.createRange(); r.selectNodeContents(tex); const s = getSelection(); s.removeAllRanges(); s.addRange(r);
    }
    box.classList.add('is-copied'); clearTimeout(box._t); box._t = setTimeout(() => box.classList.remove('is-copied'), 2400);
  }
  function light(el, ms = 1400) { if (!el) return; el.classList.add('is-lit'); clearTimeout(el._lit); el._lit = setTimeout(() => el.classList.remove('is-lit'), ms); }
  const noteFor = (mark) => root.querySelector(`.sc-sn[data-sn="${mark.dataset.sn}"]`);

  on(root, 'click', (e) => {
    const t = e.target;
    const inStage = stage.contains(t);
    if (inStage && !isYours() && win.contains(t)) finish();
    const a = t.closest('a, button, .sc-fig, .sc-veil'); if (!a) return;
    if (a.matches('[data-tour="ref-fig"], .sc-fig')) { e.preventDefault(); setFig(!fig.classList.contains('is-big')); return; }
    if (a.matches('.sc-veil')) { closeAll(); return; }
    if (a.matches('.sc-cite')) { e.preventDefault(); light(root.querySelector(a.getAttribute('href'))); return; }
    if (a.matches('[data-cite]')) { cite(a.closest('.sc-pub')); return; }
    if (a.matches('.sc-copy')) { copy(a); return; }
    if (a.matches('[data-pdf]') && a.closest('#pub-1') && pdf) { e.preventDefault(); setPdf(true); return; }
    if (a.matches('.sc-pdf-x')) { setPdf(false); return; }
    if (a.matches('.sc-fn')) {
      e.preventDefault(); const n = noteFor(a); if (!n) return;
      if (getComputedStyle(n).float === 'none' && n.closest('.sc-doc')) n.classList.toggle('is-open');
      light(n, 2200); return;
    }
    if (a.matches('.sc-star, .sc-corr-mark, .sc-rh-r a')) {
      const to = root.querySelector(a.getAttribute('href')) || (a.getAttribute('href') === '#top' ? root : null);
      if (!to) return;
      e.preventDefault(); to.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth', block: 'start' });
      if (to.matches('.sc-corr')) setTimeout(() => light(to, 2600), 700);
    }
  });
  on(document, 'keydown', (e) => { if (e.key === 'Escape' && (root.classList.contains('is-pdf-open') || root.classList.contains('is-fig-big'))) closeAll(); });
  on(win, 'pointerdown', () => { if (tour.playing) finish(); });
  // footnote marks light their sidenote while the pointer rests on them
  root.querySelectorAll('.sc-fn').forEach((m) => {
    on(m, 'pointerenter', () => noteFor(m)?.classList.add('is-lit'));
    on(m, 'pointerleave', () => noteFor(m)?.classList.remove('is-lit'));
  });

  // the control: read it to me, skip, read it again
  const btn = root.querySelector('.sc-ctl-btn'), say = btn?.querySelector('.sc-ctl-say');
  function label() {
    if (say) say.textContent = tour.playing ? 'Skip the reading' : isYours() ? 'Read it again' : 'Read it to me';
  }
  on(btn, 'click', () => { if (tour.playing) finish(); else again(); });
  on(root, 'tour:end', () => yours(true));

  // the page makes room when the title page grows past the stage (on a phone, as the figure or the BibTeX opens)
  function grow() {
    let g = 0;
    if (kind === 'narrow') { const s = stage.getBoundingClientRect(), b = page.getBoundingClientRect(); g = Math.max(0, b.bottom + 8 - s.bottom); }
    root.style.setProperty('--grow', g.toFixed(1) + 'px');
  }
  const ro = new ResizeObserver(grow); ro.observe(page); off.push(() => ro.disconnect());

  // the running head: shown once the title page has scrolled away; it names the section in view and its folio
  const run = root.querySelector('.sc-run'), runSec = run?.querySelector('.sc-run-sec'), runFolio = run?.querySelector('.sc-run-folio');
  if (run) {
    const secs = [...root.querySelectorAll('.sc-s[data-folio]')];
    const io1 = new IntersectionObserver(([e]) => run.style.setProperty('--run', e.isIntersecting ? 0 : 1), { threshold: 0, rootMargin: '0px 0px -100% 0px' });
    io1.observe(stage);
    const pick = () => {
      let cur = secs[0];
      for (const s of secs) if (s.getBoundingClientRect().top < innerHeight * .35) cur = s;
      if (!cur || run._cur === cur) return; run._cur = cur;
      const h = cur.querySelector('.sc-h');
      runSec.innerHTML = `<b class="sc-num">${cur.dataset.folio}</b> <span>${h ? [...h.childNodes].filter((n) => !n.classList?.contains('sc-n')).map((n) => n.textContent).join('').trim() : ''}</span>`;
      runFolio.textContent = cur.dataset.folio;
    };
    let raf = 0; const onScroll = () => { cancelAnimationFrame(raf); raf = requestAnimationFrame(pick); };
    addEventListener('scroll', onScroll, { passive: true }); off.push(() => { removeEventListener('scroll', onScroll); io1.disconnect(); });
    pick();
  }

  // the paper's columns follow the title page's scale on wide screens, so the two read as one document
  const doc = root.querySelector('.sc-doc');
  const scale = () => { if (doc) doc.style.setProperty('--k', kind === 'wide' && innerWidth >= 1100 ? Math.min(1.15, Math.max(.84, tour.L?.s || 1)).toFixed(3) : 1); };

  // the stage changed shape (a window resized past a threshold, a phone turned): rebuild the script for that layout
  let rz = 0;
  const onResize = () => { clearTimeout(rz); rz = setTimeout(relayout, 140); };
  function relayout() {
    const k = kindNow();
    if (k === kind) { if (kind === 'narrow') measureNarrow(); scale(); grow(); return; }
    kind = k;
    root.classList.toggle('is-narrow', k === 'narrow');
    if (k === 'narrow') measureNarrow();
    Object.assign(tour, { camOn: k !== 'narrow' && !tour.still, touch: k === 'narrow' });
    root.classList.toggle('is-touch', tour.touch);
    tour.sizes.tall = k === 'narrow' ? [400, NaN] : [680, 1209];
    const t = tour.t, playing = tour.playing;
    tour.load(film(k));
    tour.render(isYours() ? tour.duration : Math.min(t, tour.duration), true);
    if (isYours()) page.scrollTop = 0;
    if (playing) tour.play();
    scale(); grow();
  }
  on(window, 'resize', onResize);
  document.fonts?.ready.then(() => { if (kind === 'narrow') measureNarrow(); scale(); grow(); });
  tour.ready?.then?.(() => scale());

  // when to read: never under ?t= (a frozen check frame); reduced motion and ?thumb get one calm frame;
  // otherwise once, a beat after the title page is on screen
  if (fixed) return () => off.forEach((f) => f());
  if (reduced) { tour.render(tour.duration, true); yours(true); }
  else if (thumb) tour.render(tour.api.marks.poster ?? 0, true);
  else {
    let wait = 0, done = false;
    const io = new IntersectionObserver(([e]) => {
      clearTimeout(wait);
      if (e.isIntersecting && !done) wait = setTimeout(() => { done = true; if (!isYours()) { tour.play(); label(); } }, 1100);
    }, { threshold: .4 });
    io.observe(stage); off.push(() => { io.disconnect(); clearTimeout(wait); });
  }
  label();
  return () => off.forEach((f) => f());
}

/* tour.js: a declarative product-tour engine. The shared foundation for every StyleFeatures demo film.
   Full reference: README.md beside this file. In short:

     import { Tour, click, type, show, zoom, chapter } from './tour.js';
     new Tour(rootElement, { size: [1200, 750], steps: [ chapter('01 / 03', 'Start <em>here</em>', 'One line.'),
                                                        click('@new'), show('@modal'), type('@name', 'Hello') ] });

   Everything on screen is a pure function of one number, t (seconds). Each frame the engine works out the
   product's state at t (classes, attributes, text, CSS variables, scroll positions), the camera, the fake
   cursor and the overlays, and writes only what changed. So any moment can be rendered on its own:
   ?t=12.5 freezes there, seek(t) jumps there, and a scroll, a clock or a screen recorder can all drive it.

   Selectors ('@name' is short for [data-tour="name"]) are measured against the product as it is at the moment
   each step happens, and measured again whenever the layout changes (fonts, resize, your CSS), so editing the
   product never breaks the script. */

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const ease = (t) => t * t * t * (t * (t * 6 - 15) + 10);           // smootherstep: settles, no overshoot
const lerp = (a, b, t) => a + (b - a) * t;
const rnd = (n) => { const x = Math.sin(n * 91.7 + 13.1) * 43758.5453; return x - Math.floor(x); };
const sel = (s) => (typeof s === 'string' ? s.replace(/@([\w-]+)/g, '[data-tour="$1"]') : s);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/* ── step builders ─────────────────────────────────────────────────────────────────────────────
   Pointer steps run one after another on the script's clock. Side steps (zoom, show, hide, set, tween,
   chapter, caption) start at the current moment and let the next step start with them.
   Any step takes { at: seconds } to pin it, { wait: seconds } to start later, { parallel: true }
   so a pointer step doesn't hold up the next one, { block: true } so a side step does. */
export const move = (to, o = {}) => ({ ...o, do: 'move', to });
export const click = (to, o = {}) => ({ ...o, do: 'click', to });
export const dblclick = (to, o = {}) => ({ ...o, do: 'dblclick', to });
export const hover = (to, o = {}) => ({ ...o, do: 'hover', to });
export const type = (el, text, o = {}) => ({ ...o, do: 'type', el, text });
export const drag = (handle, o = {}) => ({ ...o, do: 'drag', handle });
export const scroll = (el, to, o = {}) => ({ ...o, do: 'scroll', el, to });
export const key = (keys, o = {}) => ({ ...o, do: 'key', keys: [].concat(keys) });
export const zoom = (to, z = 'fit', o = {}) => ({ ...o, do: 'zoom', to, z });
export const unzoom = (o = {}) => ({ ...o, do: 'zoom', to: null, z: 1 });
export const show = (el, o = {}) => ({ ...o, do: 'show', el });
export const hide = (el, o = {}) => ({ ...o, do: 'hide', el });
export const set = (el, changes, o = {}) => ({ ...o, do: 'set', el, changes });
export const tween = (el, prop, from, to, o = {}) => ({ ...o, do: 'tween', el, prop, from, to });
export const chapter = (n, title, line = '', o = {}) => ({ ...o, do: 'chapter', n, title, line });
export const caption = (text, o = {}) => ({ ...o, do: 'caption', text });
export const pause = (dur = 1) => ({ do: 'pause', dur });
export const stream = (el, o = {}) => ({ ...o, do: 'stream', el });   // reveal matches one after another, like output arriving
export const tap = click;                                                 // the same step; reads better in a touch film
export const longpress = (to, o = {}) => ({ ...o, do: 'longpress', to }); // press and hold; it fires after { hold } s
export const swipe = (on, o = {}) => ({ ...o, do: 'swipe', on });         // a finger flick: { by, scroll } or { prop, from, to } (README)
export const mark = (name, o = {}) => ({ ...o, do: 'mark', name });       // a named moment: tour.api.marks[name] is its time, and the list is in order (README)

/* eases for show / hide / tween: { ease: 'out' | 'ios' | 'spring' | (t) => t }. Default: smootherstep.
   'ios' is a critically damped spring (UIKit pushes and sheets), 'spring' overshoots by about 3%. */
export const eases = {
  linear: (t) => t,
  out: (t) => 1 - Math.pow(1 - t, 3),
  ios: (t) => (t >= 1 ? 1 : (1 - (1 + 9 * t) * Math.exp(-9 * t)) / (1 - 10 * Math.exp(-9))),
